/// <summary>
/// Initializes the record based on a <c>PurchTable</c> record.
/// </summary>
/// <param name="_purchTable">
/// A <c>PurchTable</c> record to initialize based on.
/// </param>
void  initFromPurchTable(PurchTable _purchTable)
{
    next initFromPurchTable(_purchTable);

    this.AVAWorkerPurchPlacer           = _purchTable.WorkerPurchPlacer;
    this.AVAMatchingAgreement           = _purchTable.MatchingAgreement;
    this.AVACashDisc                    = _purchTable.CashDisc;
    this.AVAPayment                     = _purchTable.Payment;
    this.AVARequester                   = _purchTable.Requester;
    this.AVAPurchConfirmationDueDate    = _purchTable.KCS_DLMConfirmMaturityDate;
    this.AVAEmailRecipient              = _purchTable.Email;
}
